namespace Synergos.CMS.Application.Dto.Constants;

/// <summary>
/// Stable GUID keys for Umbraco Content Types (Compositions, Element
/// Types, Document Types) that have been exported to
/// <c>Synergos.CMS.Web/uSync/v9/ContentTypes/</c>.
/// </summary>
/// <remarks>
/// Per ADR 0008, uSync XMLs are the source of truth; this class is a
/// typed reference for code that needs to resolve types by GUID.
///
/// GUID assignment policy:
/// <list type="bullet">
///   <item>GUIDs are <b>generated by Umbraco</b> when the type is
///   created in the backoffice. uSync captures the value on export
///   (feature <c>feedback_no_preassigned_guids_usync</c> in agent memory).</item>
///   <item>Constants are added here <b>after</b> the uSync XML exists —
///   never before. The quadruple verification from
///   <c>MIGRATION_GUARDRAILS §6.2</c> runs on the real captured GUID.</item>
///   <item>The Epic Fail 2 prefix convention (<c>b1*-b8*</c> Compositions,
///   <c>c3*-ce*</c> Element Types, <c>d2*-d6*</c> Document Types) is a
///   <b>historical reference</b> (see <c>history_guid_registry_epicfail2</c>
///   in agent memory), not a rule. Current GUIDs are whatever Umbraco
///   generates; no attempt to force them into legacy ranges.</item>
/// </list>
/// </remarks>
public static class ContentTypeKeys
{
    /// <summary>
    /// <c>compSeo</c> — Composition providing the <c>seoTitle</c>
    /// property. Composed into Document Types that need SEO metadata;
    /// not instantiable as Content (<c>IsElement=false</c>).
    /// </summary>
    /// <remarks>
    /// Source: <c>Synergos.CMS.Web/uSync/v9/ContentTypes/compseo.config</c>.
    /// GUID generated by Umbraco on backoffice save (Ola 4 of the
    /// migration plan). Minor visual-naming debt tracked in
    /// <c>refactor-docs/migration/03-migration-inventory.md</c>
    /// (Ola 4 execution log) — does not affect the contract of the
    /// alias / GUID used from code.
    /// </remarks>
    public static readonly Guid CompSeo =
        Guid.Parse("85e75635-b950-4583-b5ca-2a51c08892e3");

    /// <summary>
    /// <c>pageBasic</c> — Minimal Document Type (ADR 0014). Smoke test
    /// for the RenderController → Response DTO → Razor Template
    /// pipeline. Composes <see cref="CompSeo"/> for <c>seoTitle</c> and
    /// adds a single richtext <c>body</c> property.
    /// </summary>
    /// <remarks>
    /// Source: <c>Synergos.CMS.Web/uSync/v9/ContentTypes/page-basic.config</c>.
    /// GUID generated fresh by the agent (Flow B — agent-authored XML,
    /// see <c>feedback_no_preassigned_guids_usync</c>) with quadruple
    /// verification pre-commit (MIGRATION_GUARDRAILS §6.2). Import into
    /// the DB happens when the architect runs <c>uSync Import</c> in
    /// the backoffice.
    /// </remarks>
    public static readonly Guid PageBasic =
        Guid.Parse("95fef9ef-a6b2-454d-af54-b58d03b2a88e");

    /// <summary>
    /// <c>compCoreBase</c> — Base composition for technical metadata
    /// (e.g. <c>internalNotes</c>). Composed into every core DocType.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcorebase.config</c>.
    /// Flow B (agent-authored) — Ola 8.
    /// </remarks>
    public static readonly Guid CompCoreBase =
        Guid.Parse("5e2ec6b8-7f65-4c26-8c20-1b9a72bed2f8");

    /// <summary>
    /// <c>compCoreLifecycle</c> — Editorial lifecycle metadata
    /// (<c>publishingNotes</c>). Composed into DocTypes that need
    /// formal editorial traceability.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcorelifecycle.config</c>.
    /// Flow B — Ola 8.
    /// </remarks>
    public static readonly Guid CompCoreLifecycle =
        Guid.Parse("77440708-6cce-4a20-8679-212aaadd92eb");

    /// <summary>
    /// <c>siteRoot</c> — Top-level site container. One per
    /// brand/deployment (multi-brand handled in a later wave).
    /// Hosts pageBase, pageBare and pageBasic as children.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/siteroot.config</c>.
    /// Flow B — Ola 8.
    /// </remarks>
    public static readonly Guid SiteRoot =
        Guid.Parse("03d85835-06e4-4d8b-bd18-6088a529cf57");

    /// <summary>
    /// <c>pageBase</c> — Canonical editorial page under siteRoot.
    /// Composes compCoreBase + compCoreLifecycle + compSeo. Adds a
    /// richtext <c>body</c>.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/page-base.config</c>.
    /// Flow B — Ola 8.
    /// </remarks>
    public static readonly Guid PageBase =
        Guid.Parse("b4df602f-1c16-4ad7-8b57-69aa64ff6ad1");

    /// <summary>
    /// <c>pageBare</c> — Chrome-less page variant. Composes
    /// compCoreBase + compSeo. Template emits only the body without
    /// shared layout chrome.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/page-bare.config</c>.
    /// Flow B — Ola 8.
    /// </remarks>
    public static readonly Guid PageBare =
        Guid.Parse("0bd9379d-07eb-49de-802a-e68483322582");

    /// <summary>
    /// <c>compIntegration</c> — Base composition for elements that
    /// integrate an external artifact: SynHost blocks (CDN-backed),
    /// iframe hosts, script hosts. Provides a <c>configOverride</c>
    /// JSON field. Variations=Nothing.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compintegration.config</c>.
    /// Flow B (agent-authored) — Ola 8.5.
    /// </remarks>
    public static readonly Guid CompIntegration =
        Guid.Parse("84fe7a74-faa4-434f-acf1-b1ae1a50a90f");

    /// <summary>
    /// <c>elementIntIframeHost</c> — Element Type for embedding an
    /// iframe from an external origin (YouTube, Vimeo, Typeform, etc.).
    /// Not a CDN block; use <c>elementSyn*</c> for those.
    /// Variations=Culture.
    /// </summary>
    public static readonly Guid ElementIntIframeHost =
        Guid.Parse("5fe3cde6-a3b1-4afe-a5a4-a3730594ef29");

    /// <summary>
    /// <c>elementIntScriptHost</c> — Element Type for injecting a
    /// <c>&lt;script&gt;</c> from an allowlisted origin
    /// (<c>Synergos:Cdn:AllowedScriptOrigins</c> in appsettings).
    /// Variations=Nothing.
    /// </summary>
    public static readonly Guid ElementIntScriptHost =
        Guid.Parse("7c9b40d5-61f5-4b61-a4e3-79f14e9c7ef6");

    /// <summary>
    /// <c>elementSynAvatar</c> — SynHost pilot block. DOM:
    /// <c>&lt;synergos-avatar&gt;</c>. Bundle resolved at runtime via
    /// <see cref="Interfaces.IBundleRegistryClient"/>.
    /// </summary>
    public static readonly Guid ElementSynAvatar =
        Guid.Parse("28d5b6b8-200c-43a4-872a-d8958a392d97");

    /// <summary>
    /// <c>elementSynBadge</c> — SynHost pilot block. DOM:
    /// <c>&lt;synergos-badge&gt;</c>.
    /// </summary>
    public static readonly Guid ElementSynBadge =
        Guid.Parse("26965c38-03f5-44b2-a3e8-8daa5288143c");

    /// <summary>
    /// <c>elementSynDivider</c> — SynHost pilot block. DOM:
    /// <c>&lt;synergos-divider&gt;</c>. No own props; configurable
    /// only via <c>configOverride</c>.
    /// </summary>
    public static readonly Guid ElementSynDivider =
        Guid.Parse("e522308f-8591-4974-9a2f-b62dae8690fb");

    /// <summary>
    /// <c>compContentHeading</c> — Reusable heading composition
    /// (<c>headingTitle</c> + <c>headingSubtitle</c>). Composed into
    /// Element Types that need a typed header. Variations=Culture.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcontentheading.config</c>.
    /// Flow B — Ola 9. Folder <c>Compositions/Content</c>.
    /// </remarks>
    public static readonly Guid CompContentHeading =
        Guid.Parse("eb4bd93f-f9d1-44dd-b85e-d64b2084a3ad");

    /// <summary>
    /// <c>compContentText</c> — Reusable richtext body composition
    /// (<c>textBody</c>). Composed into Element Types that need their
    /// own paragraph of copy. Variations=Culture.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcontenttext.config</c>.
    /// Flow B — Ola 9.
    /// </remarks>
    public static readonly Guid CompContentText =
        Guid.Parse("71d74897-c807-452c-83c3-04c94fd1414b");

    /// <summary>
    /// <c>compContentCta</c> — Reusable Call-To-Action composition
    /// (<c>ctaLabel</c>, <c>ctaUrl</c>, <c>ctaOpenInNewTab</c>).
    /// Composed into Element Types that invite an action.
    /// Variations=Culture (label + URL); <c>ctaOpenInNewTab</c>
    /// invariant.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcontentcta.config</c>.
    /// Flow B — Ola 9.
    /// </remarks>
    public static readonly Guid CompContentCta =
        Guid.Parse("92cb0070-0f4d-43a0-84a7-102f60dc41b4");

    /// <summary>
    /// <c>compContentMedia</c> — Reusable media reference composition
    /// (<c>mediaReference</c> + <c>mediaAlt</c> + <c>mediaCaption</c>).
    /// Alt mandatory per WCAG 1.1.1. Variations=Culture on all three.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcontentmedia.config</c>.
    /// Flow B — Ola 10. Folder <c>Compositions/Content/Media</c>.
    /// </remarks>
    public static readonly Guid CompContentMedia =
        Guid.Parse("e2a29901-8155-4d36-80ab-f42b2452a45b");

    /// <summary>
    /// <c>compContentMetadata</c> — Editorial (non-SEO) metadata:
    /// <c>metaKeywords</c> + <c>metaSummary</c>. For SEO use compSeo.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcontentmetadata.config</c>.
    /// Flow B — Ola 10. Folder <c>Compositions/Content/Meta</c>.
    /// </remarks>
    public static readonly Guid CompContentMetadata =
        Guid.Parse("84383010-4c98-4a2c-b67f-a347b00cde81");

    /// <summary>
    /// <c>compContentDate</c> — Editorial date (<c>contentDate</c>
    /// Nothing + <c>contentDateLabel</c> Culture). Distinct from
    /// Umbraco's native createDate/updateDate.
    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcontentdate.config</c>.
    /// Flow B — Ola 10.
    /// </remarks>
    public static readonly Guid CompContentDate =
        Guid.Parse("986da42d-9203-4270-8234-3f8255abdbdf");
}
